8	public class AddReminderTool implements Tool {
9	
10	    private final ReminderStore store;
11	
12	    public AddReminderTool(ReminderStore store) {
13	        this.store = store;
14	    }
15	
16	    @Override
17	    public String name() {
18	        return "add_reminder";
19	    }
20	
21	    @Override
22	    public String description() {
23	        return "Adds a reminder with the given text and due date/time (ISO-8601).";
24	    }
25	
26	    @Override
27	    public String jsonSchema() {
28	        return "{\"type\":\"object\",\"properties\":{"
29	                + "\"text\":{\"type\":\"string\"},"
30	                + "\"dueIso\":{\"type\":\"string\"}"
31	                + "},\"required\":[\"text\",\"dueIso\"]}";
32	    }
33	
34	    @Override
35	    public String execute(Map<String, Object> args) throws ToolError {
36	        String text = stringArg(args, "text");
37	        if (text == null || text.trim().isEmpty()) {
38	            throw new ToolError("text is required and must not be blank");
39	        }
40	        String dueIso = stringArg(args, "dueIso");
41	        validateDueIso(dueIso);
42	
43	        ReminderStore.ReminderEntry entry = store.add(text.trim(), dueIso);
44	        return "Reminder added: \"" + entry.getText() + "\", due " + entry.getDueIso();
45	    }
46	
47	    private void validateDueIso(String dueIso) throws ToolError {
48	        if (dueIso == null || dueIso.trim().isEmpty()) {
49	            throw new ToolError("dueIso is required and must be a valid ISO-8601 date-time");
50	        }
51	        try {
52	            Instant.parse(dueIso);
53	            return;
54	        } catch (DateTimeParseException e) {
55	            // fall through to try OffsetDateTime
56	        }
57	        try {
58	            OffsetDateTime.parse(dueIso);
59	        } catch (DateTimeParseException e) {
60	            throw new ToolError("dueIso must be a valid ISO-8601 date-time");
61	        }
62	    }
