package ru.assistant.agent;

import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import ru.assistant.infra.AuditLog;
import ru.assistant.infra.LogEvents;
import ru.assistant.llm.ChatResponse;
import ru.assistant.llm.LlmException;
import ru.assistant.llm.MockLlmClient;
import ru.assistant.mail.MailChannel;
import ru.assistant.mail.MailChannelException;
import ru.assistant.mail.MockMailChannel;
import ru.assistant.mail.Msg;
import ru.assistant.tools.Tool;
import ru.assistant.tools.ToolRegistry;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class MailProcessingServiceTest {

    @Rule
    public TemporaryFolder tmp = new TemporaryFolder();

    private final Msg msg1 = new Msg("id-1", "alice@example.com", "Subj", "Hello", "2026-08-13T10:00:00Z");
    private final Msg msg2 = new Msg("id-2", "bob@example.com", "Subj 2", "Hi", "2026-08-13T11:00:00Z");

    @Test
    public void singleMessageWithFinalAnswerIsRepliedToAndMarkedSeen() throws Exception {
        MockMailChannel channel = new MockMailChannel(Arrays.asList(msg1));
        SeenStore seenStore = new SeenStore(seenFile());
        AgentToolLoop loop = new AgentToolLoop(
                new MockLlmClient(Arrays.asList(new ChatResponse("Hi there!", null, "stop"))),
                new ToolRegistry(Collections.<Tool>emptyList()), 5);
        MailProcessingService service = new MailProcessingService(channel, seenStore, loop);

        service.processCycle();

        assertEquals(1, channel.getSentReplies().size());
        assertEquals(msg1, channel.getSentReplies().get(0).getOriginal());
        assertEquals("Hi there!", channel.getSentReplies().get(0).getBody());
    }

    @Test
    public void repeatedDeliveryOfSameMessageIsRepliedToOnlyOnce() throws Exception {
        RepeatingMailChannel channel = new RepeatingMailChannel(msg1);
        SeenStore seenStore = new SeenStore(seenFile());
        AgentToolLoop loop = new AgentToolLoop(
                new MockLlmClient(Arrays.asList(new ChatResponse("Hi there!", null, "stop"))),
                new ToolRegistry(Collections.<Tool>emptyList()), 5);
        MailProcessingService service = new MailProcessingService(channel, seenStore, loop);

        service.processCycle();
        service.processCycle();

        assertEquals(1, channel.replies.size());
    }

    @Test
    public void newInstanceAfterRestartDoesNotResendReplyForAlreadySeenMessage() throws Exception {
        Path file = seenFile();
        RepeatingMailChannel channel = new RepeatingMailChannel(msg1);
        AgentToolLoop loop = new AgentToolLoop(
                new MockLlmClient(Arrays.asList(new ChatResponse("Hi there!", null, "stop"))),
                new ToolRegistry(Collections.<Tool>emptyList()), 5);
        MailProcessingService first = new MailProcessingService(channel, new SeenStore(file), loop);
        first.processCycle();

        MailProcessingService afterRestart = new MailProcessingService(channel, new SeenStore(file), loop);
        afterRestart.processCycle();

        assertEquals(1, channel.replies.size());
    }

    @Test
    public void llmFailureDoesNotSendReplyAndUnmarksMessageForRetry() throws Exception {
        MockMailChannel channel = new MockMailChannel(Arrays.asList(msg1));
        SeenStore seenStore = new SeenStore(seenFile());
        MockLlmClient llm = new MockLlmClient(Collections.<ChatResponse>emptyList());
        llm.throwOnNextCall(new LlmException("simulated LLM outage"));
        AgentToolLoop loop = new AgentToolLoop(llm, new ToolRegistry(Collections.<Tool>emptyList()), 5);
        MailProcessingService service = new MailProcessingService(channel, seenStore, loop);

        service.processCycle();

        assertTrue(channel.getSentReplies().isEmpty());
        assertTrue(seenStore.markIfNew(msg1.getId()));
    }

    @Test
    public void mailChannelFetchFailureDoesNotThrowAndNextCycleWorksNormally() throws Exception {
        MockMailChannel channel = new MockMailChannel(Arrays.asList(msg1));
        channel.setThrowOnFetch(true);
        SeenStore seenStore = new SeenStore(seenFile());
        AgentToolLoop loop = new AgentToolLoop(
                new MockLlmClient(Arrays.asList(new ChatResponse("Hi there!", null, "stop"))),
                new ToolRegistry(Collections.<Tool>emptyList()), 5);
        MailProcessingService service = new MailProcessingService(channel, seenStore, loop);

        service.processCycle();
        assertTrue(channel.getSentReplies().isEmpty());

        channel.setThrowOnFetch(false);
        service.processCycle();

        assertEquals(1, channel.getSentReplies().size());
    }

    @Test
    public void replyFailureForOneMessageDoesNotStopProcessingOfOthers() throws Exception {
        FailOnSecondReplyMailChannel channel = new FailOnSecondReplyMailChannel(msg1, msg2);
        SeenStore seenStore = new SeenStore(seenFile());
        AgentToolLoop loop = new AgentToolLoop(
                new MockLlmClient(Arrays.asList(
                        new ChatResponse("Reply 1", null, "stop"),
                        new ChatResponse("Reply 2", null, "stop"))),
                new ToolRegistry(Collections.<Tool>emptyList()), 5);
        MailProcessingService service = new MailProcessingService(channel, seenStore, loop);

        service.processCycle();

        assertEquals(1, channel.replies.size());
        assertEquals(msg1, channel.replies.get(0).getOriginal());
        assertTrue(seenStore.markIfNew(msg2.getId()));
    }

    @Test
    public void keyEventsAreRecordedInAuditLogWhenAuditLogProvided() throws Exception {
        MockMailChannel channel = new MockMailChannel(Arrays.asList(msg1));
        SeenStore seenStore = new SeenStore(seenFile());
        AgentToolLoop loop = new AgentToolLoop(
                new MockLlmClient(Arrays.asList(new ChatResponse("Hi there!", null, "stop"))),
                new ToolRegistry(Collections.<Tool>emptyList()), 5);
        AuditLog auditLog = new AuditLog(auditFile());
        MailProcessingService service = new MailProcessingService(channel, seenStore, loop, auditLog);

        service.processCycle();

        assertTrue(auditLog.verify());
        List<String> lines = Files.readAllLines(auditFile(), StandardCharsets.UTF_8);
        assertTrue(containsEventKey(lines, LogEvents.AGENT_MAIL_SEEN));
        assertTrue(containsEventKey(lines, LogEvents.AGENT_REPLY_SENT));
    }

    private Path seenFile() {
        return tmp.getRoot().toPath().resolve("seen.json");
    }

    private Path auditFile() {
        return tmp.getRoot().toPath().resolve("audit.jsonl");
    }

    private boolean containsEventKey(List<String> lines, String eventKey) {
        for (String line : lines) {
            if (line.contains("\"eventKey\":\"" + eventKey + "\"")) {
                return true;
            }
        }
        return false;
    }

    /**
     * Test-only stub simulating an Outlook sync glitch: always reports the same
     * message as unread, regardless of prior reply() calls.
     */
    private static class RepeatingMailChannel implements MailChannel {
        private final Msg fixedMessage;
        private final List<MockMailChannel.SentReply> replies = new ArrayList<>();

        RepeatingMailChannel(Msg fixedMessage) {
            this.fixedMessage = fixedMessage;
        }

        @Override
        public List<Msg> fetchUnread() {
            return Arrays.asList(fixedMessage);
        }

        @Override
        public void reply(Msg original, String body) throws MailChannelException {
            replies.add(new MockMailChannel.SentReply(original, body));
        }
    }

    /**
     * Test-only stub: fetches both messages but fails reply() for the second one only,
     * to verify one failing message doesn't stop processing of the rest of the batch.
     */
    private static class FailOnSecondReplyMailChannel implements MailChannel {
        private final Msg first;
        private final Msg second;
        private final List<MockMailChannel.SentReply> replies = new ArrayList<>();

        FailOnSecondReplyMailChannel(Msg first, Msg second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public List<Msg> fetchUnread() {
            return Arrays.asList(first, second);
        }

        @Override
        public void reply(Msg original, String body) throws MailChannelException {
            if (original.equals(second)) {
                throw new MailChannelException("simulated reply failure for second message");
            }
            replies.add(new MockMailChannel.SentReply(original, body));
        }
    }
}

package ru.assistant.agent;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import ru.assistant.infra.AuditLog;
import ru.assistant.infra.LogEvents;
import ru.assistant.llm.ChatMessage;
import ru.assistant.llm.ChatResponse;
import ru.assistant.llm.LlmClient;
import ru.assistant.llm.LlmException;
import ru.assistant.llm.ToolCall;
import ru.assistant.llm.ToolSpec;
import ru.assistant.tools.Tool;
import ru.assistant.tools.ToolError;
import ru.assistant.tools.ToolRegistry;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public class AgentToolLoop {

    private final LlmClient llmClient;
    private final ToolRegistry toolRegistry;
    private final int maxSteps;
    private final AuditLog auditLog;
    private final ObjectMapper mapper = new ObjectMapper();

    public AgentToolLoop(LlmClient llmClient, ToolRegistry toolRegistry, int maxSteps) {
        this(llmClient, toolRegistry, maxSteps, null);
    }

    public AgentToolLoop(LlmClient llmClient, ToolRegistry toolRegistry, int maxSteps, AuditLog auditLog) {
        this.llmClient = llmClient;
        this.toolRegistry = toolRegistry;
        this.maxSteps = maxSteps;
        this.auditLog = auditLog;
    }

    public String run(String userMessage) throws LlmException {
        List<ChatMessage> messages = new ArrayList<>();
        messages.add(ChatMessage.user(userMessage));
        List<ToolSpec> toolSpecs = toolRegistry.toToolSpecs();

        for (int step = 0; step < maxSteps; step++) {
            ChatResponse response = llmClient.chat(messages, toolSpecs);

            if (response.getToolCalls().isEmpty()) {
                return response.getContent();
            }

            messages.add(ChatMessage.assistant(response.getContent()));
            for (ToolCall call : response.getToolCalls()) {
                String result = executeToolCall(call);
                messages.add(ChatMessage.tool(call.getId(), result));
            }
        }

        appendAudit(LogEvents.AGENT_MAXSTEPS_EXCEEDED, "{\"maxSteps\":" + maxSteps + "}");
        return "Reached the maximum number of steps without a final answer.";
    }

    private String executeToolCall(ToolCall call) {
        appendAudit(LogEvents.AGENT_TOOL_CALL, "{\"tool\":\"" + LogEvents.jsonEscape(call.getName())
                + "\",\"args\":\"" + LogEvents.safePreview(call.getArgumentsJson()) + "\"}");

        Optional<Tool> tool = toolRegistry.get(call.getName());
        if (!tool.isPresent()) {
            return "Error: unknown tool '" + call.getName() + "'";
        }

        Map<String, Object> args;
        try {
            args = parseArguments(call.getArgumentsJson());
        } catch (RuntimeException e) {
            return "Error: invalid arguments for tool '" + call.getName() + "'";
        }

        try {
            return tool.get().execute(args);
        } catch (ToolError e) {
            return "Error: " + e.getMessage();
        }
    }

    private void appendAudit(String eventKey, String detailsJson) {
        if (auditLog != null) {
            auditLog.append(eventKey, detailsJson);
        }
    }

    private Map<String, Object> parseArguments(String argumentsJson) {
        if (argumentsJson == null || argumentsJson.trim().isEmpty()) {
            return java.util.Collections.emptyMap();
        }
        try {
            return mapper.readValue(argumentsJson, new TypeReference<Map<String, Object>>() {
            });
        } catch (java.io.IOException e) {
            throw new IllegalArgumentException("Invalid tool arguments JSON", e);
        }
    }
}

package ru.assistant.agent;

import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import ru.assistant.infra.AuditLog;
import ru.assistant.infra.LogEvents;
import ru.assistant.llm.ChatResponse;
import ru.assistant.llm.MockLlmClient;
import ru.assistant.llm.ToolCall;
import ru.assistant.tools.CurrentDatetimeTool;
import ru.assistant.tools.Tool;
import ru.assistant.tools.ToolError;
import ru.assistant.tools.ToolRegistry;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class AgentToolLoopTest {

    @Rule
    public TemporaryFolder tmp = new TemporaryFolder();

    private static final Clock FIXED_CLOCK =
            Clock.fixed(Instant.parse("2026-08-13T10:00:00Z"), ZoneOffset.UTC);

    @Test
    public void scenarioA_singleToolCallThenFinalAnswer() throws Exception {
        ToolRegistry registry = new ToolRegistry(Arrays.asList((Tool) new CurrentDatetimeTool(FIXED_CLOCK)));
        MockLlmClient llm = new MockLlmClient(Arrays.asList(
                new ChatResponse(null, Arrays.asList(new ToolCall("call1", "current_datetime", "{}")), "tool_calls"),
                new ChatResponse("The current time is 2026-08-13T10:00:00Z", null, "stop")
        ));
        AgentToolLoop loop = new AgentToolLoop(llm, registry, 5);

        String result = loop.run("What time is it?");

        assertEquals("The current time is 2026-08-13T10:00:00Z", result);
    }

    @Test
    public void scenarioB_noToolCallsReturnsImmediateFinalAnswer() throws Exception {
        ToolRegistry registry = new ToolRegistry(Collections.<Tool>emptyList());
        MockLlmClient llm = new MockLlmClient(Arrays.asList(
                new ChatResponse("Hello there", null, "stop")
        ));
        AgentToolLoop loop = new AgentToolLoop(llm, registry, 5);

        String result = loop.run("hi");

        assertEquals("Hello there", result);
    }

    @Test
    public void scenarioC_maxStepsExceededStopsWithPredictableFallback() throws Exception {
        ToolRegistry registry = new ToolRegistry(Arrays.asList((Tool) new AlwaysOkTool()));
        MockLlmClient llm = new MockLlmClient(Arrays.asList(
                new ChatResponse(null, Arrays.asList(new ToolCall("c1", "always_ok", "{}")), "tool_calls"),
                new ChatResponse(null, Arrays.asList(new ToolCall("c2", "always_ok", "{}")), "tool_calls"),
                new ChatResponse(null, Arrays.asList(new ToolCall("c3", "always_ok", "{}")), "tool_calls")
        ));
        AgentToolLoop loop = new AgentToolLoop(llm, registry, 3);

        String result = loop.run("keep going forever");

        assertTrue(result.length() > 0);
    }

    @Test
    public void scenarioD_unknownToolNameDoesNotCrashLoop() throws Exception {
        ToolRegistry registry = new ToolRegistry(Collections.<Tool>emptyList());
        MockLlmClient llm = new MockLlmClient(Arrays.asList(
                new ChatResponse(null, Arrays.asList(new ToolCall("id1", "does_not_exist", "{}")), "tool_calls"),
                new ChatResponse("Sorry, I could not complete that.", null, "stop")
        ));
        AgentToolLoop loop = new AgentToolLoop(llm, registry, 5);

        String result = loop.run("do something unsupported");

        assertEquals("Sorry, I could not complete that.", result);
    }

    @Test
    public void scenarioE_invalidArgumentsJsonDoesNotCrashLoop() throws Exception {
        ToolRegistry registry = new ToolRegistry(Arrays.asList((Tool) new CurrentDatetimeTool(FIXED_CLOCK)));
        MockLlmClient llm = new MockLlmClient(Arrays.asList(
                new ChatResponse(null, Arrays.asList(new ToolCall("id1", "current_datetime", "not-json")), "tool_calls"),
                new ChatResponse("Final answer despite bad args", null, "stop")
        ));
        AgentToolLoop loop = new AgentToolLoop(llm, registry, 5);

        String result = loop.run("please call with garbage args");

        assertEquals("Final answer despite bad args", result);
    }

    @Test
    public void scenarioF_toolThrowsToolErrorDoesNotCrashLoop() throws Exception {
        ToolRegistry registry = new ToolRegistry(Arrays.asList((Tool) new AlwaysThrowsTool()));
        MockLlmClient llm = new MockLlmClient(Arrays.asList(
                new ChatResponse(null, Arrays.asList(new ToolCall("id1", "always_throws", "{}")), "tool_calls"),
                new ChatResponse("Recovered from tool failure", null, "stop")
        ));
        AgentToolLoop loop = new AgentToolLoop(llm, registry, 5);

        String result = loop.run("trigger a tool failure");

        assertEquals("Recovered from tool failure", result);
    }

    @Test
    public void toolCallIsRecordedInAuditLogWhenAuditLogProvided() throws Exception {
        ToolRegistry registry = new ToolRegistry(Arrays.asList((Tool) new CurrentDatetimeTool(FIXED_CLOCK)));
        MockLlmClient llm = new MockLlmClient(Arrays.asList(
                new ChatResponse(null, Arrays.asList(new ToolCall("call1", "current_datetime", "{}")), "tool_calls"),
                new ChatResponse("The current time is 2026-08-13T10:00:00Z", null, "stop")
        ));
        AuditLog auditLog = new AuditLog(auditFile());
        AgentToolLoop loop = new AgentToolLoop(llm, registry, 5, auditLog);

        loop.run("What time is it?");

        assertTrue(auditLog.verify());
        List<String> lines = Files.readAllLines(auditFile(), StandardCharsets.UTF_8);
        assertTrue(containsEventKey(lines, LogEvents.AGENT_TOOL_CALL));
    }

    @Test
    public void maxStepsExceededIsRecordedInAuditLogWhenAuditLogProvided() throws Exception {
        ToolRegistry registry = new ToolRegistry(Arrays.asList((Tool) new AlwaysOkTool()));
        MockLlmClient llm = new MockLlmClient(Arrays.asList(
                new ChatResponse(null, Arrays.asList(new ToolCall("c1", "always_ok", "{}")), "tool_calls"),
                new ChatResponse(null, Arrays.asList(new ToolCall("c2", "always_ok", "{}")), "tool_calls")
        ));
        AuditLog auditLog = new AuditLog(auditFile());
        AgentToolLoop loop = new AgentToolLoop(llm, registry, 2, auditLog);

        loop.run("keep going forever");

        List<String> lines = Files.readAllLines(auditFile(), StandardCharsets.UTF_8);
        assertTrue(containsEventKey(lines, LogEvents.AGENT_MAXSTEPS_EXCEEDED));
    }

    private Path auditFile() {
        return tmp.getRoot().toPath().resolve("audit.jsonl");
    }

    private boolean containsEventKey(List<String> lines, String eventKey) {
        for (String line : lines) {
            if (line.contains("\"eventKey\":\"" + eventKey + "\"")) {
                return true;
            }
        }
        return false;
    }

    private static class AlwaysOkTool implements Tool {
        @Override
        public String name() {
            return "always_ok";
        }

        @Override
        public String description() {
            return "test stub tool that always succeeds";
        }

        @Override
        public String jsonSchema() {
            return "{\"type\":\"object\",\"properties\":{}}";
        }

        @Override
        public String execute(Map<String, Object> args) throws ToolError {
            return "ok";
        }
    }

    private static class AlwaysThrowsTool implements Tool {
        @Override
        public String name() {
            return "always_throws";
        }

        @Override
        public String description() {
            return "test stub tool that always throws ToolError";
        }

        @Override
        public String jsonSchema() {
            return "{\"type\":\"object\",\"properties\":{}}";
        }

        @Override
        public String execute(Map<String, Object> args) throws ToolError {
            throw new ToolError("simulated tool failure");
        }
    }
}

package ru.assistant.tools;

import java.util.Map;

public interface Tool {

    String name();

    String description();

    /**
     * Raw JSON Schema string describing the tool's parameters object,
     * e.g. {"type":"object","properties":{...},"required":[...]}.
     */
    String jsonSchema();

    String execute(Map<String, Object> args) throws ToolError;
}

package ru.assistant.infra;

public class LogEvents {

    public static final String AGENT_MAIL_SEEN = "agent_mail_seen";
    public static final String AGENT_TOOL_CALL = "agent_tool_call";
    public static final String AGENT_REPLY_SENT = "agent_reply_sent";
    public static final String LLM_FAILED = "llm_failed";
    public static final String MAIL_CHANNEL_ERROR = "mail_channel_error";
    public static final String AGENT_MAXSTEPS_EXCEEDED = "agent_maxsteps_exceeded";

    private LogEvents() {
    }

    public static String safePreview(String text) {
        if (text == null) {
            return "<null>";
        }
        String hash = Sha256.hex(text);
        return "len=" + text.length() + " sha256=" + hash.substring(0, 12);
    }

    public static String jsonEscape(String text) {
        if (text == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder(text.length());
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == '"' || c == '\\') {
                sb.append('\\');
            }
            sb.append(c);
        }
        return sb.toString();
    }
}

